<template><div><v-alert v-if="graph.truncated" type="warning" variant="tonal" density="compact" class="mb-3">Traversal was capped; the table contains a partial topology.</v-alert><div class="table-wrap"><table><thead><tr><th>Direction</th><th>Relation</th><th>Resource</th><th>Evidence</th><th>Confidence</th></tr></thead><tbody><tr v-for="row in rows" :key="`${row.relation.from}-${row.relation.to}-${row.relation.type}`"><td>{{ row.direction }}</td><td>{{ row.relation.type }}</td><td><router-link :to="resourceRoute(row.resource)">{{ row.resource?.provenance.name || 'unknown' }}</router-link><small>{{ row.resource?.provenance.kind }}</small></td><td>{{ row.relation.evidence }}<small>{{ row.relation.fieldPath || 'field unknown' }}</small></td><td>{{ row.relation.confidence }}</td></tr><tr v-if="!rows.length"><td colspan="5">No proven relationships are present in this snapshot.</td></tr></tbody></table></div></div></template>
<script setup lang="ts">
import { computed } from 'vue'
import type { SreGraph,SreResource } from '@/api/sre'
const props=defineProps<{ graph:SreGraph; rootKey:string }>()
const rows=computed(()=>props.graph.relations.map(relation=>{const outgoing=relation.from===props.rootKey,key=outgoing?relation.to:relation.from;return{relation,direction:outgoing?'outgoing':'incoming',resource:props.graph.resources.find(resource=>resource.key===key)}}))
function opaqueId(key:string){const bytes=new TextEncoder().encode(key);let binary='';bytes.forEach(byte=>binary+=String.fromCharCode(byte));return btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function resourceRoute(resource?:SreResource){if(!resource)return'/sre/landscape';const id=opaqueId(resource.key),kind=resource.provenance.kind.toLowerCase();if(kind.includes('vm'))return`/sre/vms/${id}`;if(kind==='shoot')return`/sre/shoots/${id}`;if(kind.includes('node'))return`/sre/nodes/${id}`;if(kind==='zone')return`/sre/zones/${encodeURIComponent(resource.provenance.name)}`;return`/sre/dependencies/${id}`}
</script>
<style scoped>.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--ic-border);vertical-align:top}th{color:var(--ic-text-muted);font-size:11px;text-transform:uppercase}td small{display:block;color:var(--ic-text-muted);margin-top:2px}a{color:rgb(var(--v-theme-primary));text-decoration:none}</style>
